import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

extern __shared__ float smem_raw[];

__global__ void conv2d_tiled_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int K, int stride, int padding,
    int Hout, int Wout,
    int TILE_H, int TILE_W, int IH_tile, int IW_tile)
{
  int n = blockIdx.z;
  int tile_oh0 = blockIdx.y * TILE_H;
  int tile_ow0 = blockIdx.x * TILE_W;

  int tx = threadIdx.x % TILE_W;
  int ty = threadIdx.x / TILE_W;

  int oh = tile_oh0 + ty;
  int ow = tile_ow0 + tx;

  int ih0 = tile_oh0 * stride - padding;
  int iw0 = tile_ow0 * stride - padding;

  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * (int64_t)Cin * H * Win),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * (int64_t)Cout * Hout * Wout),
      make_shape(Cout, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));

  auto mW = make_tensor(
      make_gmem_ptr(Wt),
      make_shape(Cout, Cin, K, K),
      make_stride((int64_t)Cin * K * K, (int64_t)K * K, (int64_t)K, Int<1>{}));

  // Shared memory tensor for the input tile: (Cin, IH_tile, IW_tile)
  auto sX = make_tensor(
      make_smem_ptr(smem_raw),
      make_shape(Cin, IH_tile, IW_tile),
      make_stride(IH_tile * IW_tile, IW_tile, Int<1>{}));

  int nthreads = blockDim.x;
  int tile_elems = Cin * IH_tile * IW_tile;
  int hw_tile = IH_tile * IW_tile;

  for (int idx = threadIdx.x; idx < tile_elems; idx += nthreads) {
    int c   = idx / hw_tile;
    int rem = idx - c * hw_tile;
    int r   = rem / IW_tile;
    int cc  = rem - r * IW_tile;

    int ih = ih0 + r;
    int iw = iw0 + cc;

    float val = 0.0f;
    if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
      val = mX(c, ih, iw);
    }
    sX(c, r, cc) = val;
  }
  __syncthreads();

  if (oh < Hout && ow < Wout) {
    int local_h0 = ty * stride;
    int local_w0 = tx * stride;

    for (int co = 0; co < Cout; ++co) {
      float acc = (Bias != nullptr) ? Bias[co] : 0.0f;

      for (int ci = 0; ci < Cin; ++ci) {
        for (int kh = 0; kh < K; ++kh) {
          int r = local_h0 + kh;
          for (int kw = 0; kw < K; ++kw) {
            int cc_ = local_w0 + kw;
            float xv = sX(ci, r, cc_);
            float wv = mW(co, ci, kh, kw);
            acc += xv * wv;
          }
        }
      }
      mY(co, oh, ow) = acc;
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, K, K]");

  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);

  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1 assumed)");
  TORCH_CHECK(w.size(2) == w.size(3), "kernel must be square");
  int64_t K = w.size(2);

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  // Query device shared memory capacity to pick tile size
  int device = 0;
  cudaGetDevice(&device);
  int max_smem_optin = 0;
  cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
  if (max_smem_optin <= 0) {
    max_smem_optin = 48 * 1024; // conservative fallback
  }

  int TILE = 16;
  auto compute_smem = [&](int tile) -> size_t {
    int ih_tile = (tile - 1) * stride + (int)K;
    int iw_tile = (tile - 1) * stride + (int)K;
    return (size_t)Cin * ih_tile * iw_tile * sizeof(float);
  };

  size_t smem_bytes = compute_smem(TILE);
  if (smem_bytes > (size_t)max_smem_optin) {
    TILE = 8;
    smem_bytes = compute_smem(TILE);
  }
  if (smem_bytes > (size_t)max_smem_optin) {
    TILE = 4;
    smem_bytes = compute_smem(TILE);
  }

  int IH_tile = (TILE - 1) * stride + (int)K;
  int IW_tile = (TILE - 1) * stride + (int)K;

  cudaFuncSetAttribute(conv2d_tiled_kernel,
                        cudaFuncAttributeMaxDynamicSharedMemorySize,
                        (int)smem_bytes);

  dim3 block(TILE * TILE);
  dim3 grid(
      (unsigned)((Wout + TILE - 1) / TILE),
      (unsigned)((Hout + TILE - 1) / TILE),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_tiled_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)K, stride, padding,
      (int)Hout, (int)Wout,
      TILE, TILE, IH_tile, IW_tile
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        self._ext = conv2d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        w = self.conv1.weight
        b = self.conv1.bias
        return self._ext.conv2d_forward(
            x.contiguous(),
            w.contiguous(),
            b.contiguous() if b is not None else None,
            int(self.conv1.stride[0]),
            int(self.conv1.padding[0]),
        )

